public class Lesson {
    static final int SIZE = 5;
    static final int HEIGHT = 4;

    static void floor(String block) {
        for (int x = 0; x < SIZE; x++) {
            for (int z = 0; z < SIZE; z++) {
                Playground.placeBlock(x, 0, z, block);
            }
        }
    }

    static void walls(String block) {
        for (int y = 1; y <= HEIGHT; y++) {
            for (int x = 0; x < SIZE; x++) {
                Playground.placeBlock(x, y, 0, block);
                Playground.placeBlock(x, y, SIZE - 1, block);
            }
            for (int z = 0; z < SIZE; z++) {
                Playground.placeBlock(0, y, z, block);
                Playground.placeBlock(SIZE - 1, y, z, block);
            }
        }
    }

    static void roof(String block) {
        for (int x = 0; x < SIZE; x++) {
            for (int z = 0; z < SIZE; z++) {
                Playground.placeBlock(x, HEIGHT + 1, z, block);
            }
        }
    }

    public static void main(String[] args) {
        Playground.say("Building a house...");
        floor("oak_planks");
        walls("cobblestone");
        roof("oak_slab");
        Playground.placeBlock(2, 1, 0, "air");
        Playground.placeBlock(2, 2, 0, "air");
        Playground.particles(2, 2, 2, "happy_villager", 30);
        Playground.giveItem("diamond", 5);
        Playground.say("Done! Walk in through the gap. Here's 5 diamonds for your trouble.");
    }
}
